// ANTES: cada función que depende del vehículo repite el mismo if.
// Tarifas y velocidades INVENTADAS, solo para el ejemplo.
function costoEnvio(vehiculo, km, kg) {
  if (vehiculo === 'moto') return 1200 + 80 * km;
  if (vehiculo === 'camioneta') return 2500 + 150 * km;
  if (vehiculo === 'camion') return 9000 + 400 * km;
  throw new Error('vehículo desconocido: ' + vehiculo);
}
function horasEstimadas(vehiculo, km) {
  if (vehiculo === 'moto') return km / 35;
  if (vehiculo === 'camioneta') return km / 28;
  if (vehiculo === 'camion') return km / 22 + 0.5; // media hora de carga
  throw new Error('vehículo desconocido: ' + vehiculo);
}
