// DESPUÉS: cada vehículo es un objeto que sabe cotizarse; una fábrica los fabrica.
const VEHICULOS = new Map([
  ['moto',      () => ({ nombre: 'moto',      costo: (km) => 1200 + 80 * km,  horas: (km) => km / 35 })],
  ['camioneta', () => ({ nombre: 'camioneta', costo: (km) => 2500 + 150 * km, horas: (km) => km / 28 })],
  ['camion',    () => ({ nombre: 'camion',    costo: (km) => 9000 + 400 * km, horas: (km) => km / 22 + 0.5 })],
]);

function crearVehiculo(tipo) {
  const fabricar = VEHICULOS.get(tipo);
  if (!fabricar) throw new Error('vehículo desconocido: ' + tipo + ' (hay: ' + [...VEHICULOS.keys()].join(', ') + ')');
  return fabricar();
}

// El código que usa vehículos ya no sabe cuántos tipos hay.
function cotizar(tipo, km) {
  const v = crearVehiculo(tipo);
  return { vehiculo: v.nombre, ars: v.costo(km), horas: Number(v.horas(km).toFixed(2)) };
}
console.log(cotizar('moto', 10));
console.log(cotizar('camion', 10));

