// Un despacho con muchos datos opcionales y reglas entre ellos.
class DespachoBuilder {
  #d = { bultos: 1, prioridad: 'normal', frio: false, ventana: null };
  desde(dir)      { this.#d.origen = dir; return this; }
  hasta(dir)      { this.#d.destino = dir; return this; }
  pesoKg(kg)      { this.#d.kg = kg; return this; }
  bultos(n)       { this.#d.bultos = n; return this; }
  urgente()       { this.#d.prioridad = 'urgente'; return this; }
  conFrio()       { this.#d.frio = true; return this; }
  ventana(de, a)  { this.#d.ventana = { de, a }; return this; }

  build() {
    const d = this.#d;
    const faltan = ['origen', 'destino', 'kg'].filter((k) => d[k] === undefined);
    if (faltan.length) throw new Error('faltan: ' + faltan.join(', '));
    if (d.kg <= 0) throw new Error('el peso tiene que ser mayor que 0');
    if (d.frio && !d.ventana) throw new Error('la carga en frío exige ventana horaria');
    if (d.ventana && d.ventana.de >= d.ventana.a) throw new Error('la ventana está al revés');
    return Object.freeze({ ...d, ventana: d.ventana && Object.freeze({ ...d.ventana }) });
  }
}

const ok = new DespachoBuilder().desde('Pompeya').hasta('Palermo').pesoKg(12).conFrio().ventana(9, 11).build();
console.log(ok);
for (const armar of [
