// En JavaScript, para lo simple alcanza un objeto de opciones con valores por defecto:
function despachar({ origen, destino, kg, bultos = 1, prioridad = 'normal' }) {
  return `${origen} -> ${destino}, ${kg} kg, ${bultos} bulto(s), ${prioridad}`;
}
