// El numerador de remitos como objeto global (el «singleton» de la práctica diaria).
const Remitos = { ultimo: 0, siguiente() { return ++this.ultimo; } };

// Dos pruebas que, solas, pasan. Juntas, la segunda depende de que la primera no haya corrido.
const pruebas = [
  ['el primer remito es el 1', () => Remitos.siguiente() === 1],
  ['otro primer remito es el 1', () => Remitos.siguiente() === 1],
];
for (const [nombre, f] of pruebas) console.log(f() ? 'ok      ' : 'FALLA   ', nombre);

// Versión sin estado global: se crea una vez al arrancar y se entrega a quien la necesita.
function crearRemitos(desde = 0) {
  let ultimo = desde;
  return { siguiente: () => ++ultimo };
}
const pruebas2 = [
  ['el primer remito es el 1', () => crearRemitos().siguiente() === 1],
  ['otro primer remito es el 1', () => crearRemitos().siguiente() === 1],
  ['retomando desde el 500 sigue el 501', () => crearRemitos(500).siguiente() === 501],
];
for (const [nombre, f] of pruebas2) console.log(f() ? 'ok      ' : 'FALLA   ', nombre);

